{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "Gallopamil, a close verapamil analogue sharing the dimethoxyphenethyl-methylamino-propyl scaffold, showed 96.3% oral bioavailability in humans, supporting that this scaffold can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Vernakalant, which shares the dimethoxyphenethylamine motif, has approximately 60% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Verapamil itself, the closest analogue, had a mean absolute oral bioavailability of 22.0% in normal subjects, meeting the F >= 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "A verapamil study reported mean oral bioavailability of 10.5%, showing that the closest analogue is borderline and first-pass metabolism can reduce F below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terameprocol, a dimethoxyphenyl-containing compound, had about 2% oral bioavailability, but its non-ionizable, poorly soluble lignan structure is much less transferable to the basic amine/lactam query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tetrabenazine, containing a dimethoxy-tetrahydroisoquinoline core, had very low systemic availability (~5%), but this is driven by rapid ketone reduction, a liability not present in the query's lactam.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the query is a verapamil-like phenylalkylamine with a lactam tail; the closest verapamil data are borderline around 20%, while high-F analogues such as gallopamil (96%), vernakalant (~60%), and norverapamil (34-49%) support F >= 20%. Low-F analogues have specific liabilities (poor solubility, ketone reduction, large P-gp substrates) that are not shared by the query.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the exact query molecule.",
    "Verapamil bioavailability data are variable around the 20% threshold, making the closest analogue borderline.",
    "The gallopamil 96.3% record lacks detailed experimental methodology.",
    "The effect of the lactam modification on first-pass metabolism relative to verapamil is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

